function stableStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(stableStringify).join(',') + ']';
  return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stableStringify(value[key])).join(',') + '}';
}

function hash16(input) {
  let h1 = 0xdeadbeef ^ input.length;
  let h2 = 0x41c6ce57 ^ input.length;
  for (let i = 0; i < input.length; i++) {
    const ch = input.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return ((h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0')).slice(0, 16);
}

function hash32(input) {
  return hash16('a:' + input) + hash16('b:' + input);
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function parseJsonIfString(value, fallback) {
  if (typeof value !== 'string') return value;
  try {
    return JSON.parse(value);
  } catch (error) {
    return fallback;
  }
}

function findFirstKey(value, names, maxDepth) {
  const wanted = new Set(names);
  const queue = [{ value, depth: 0 }];
  const seen = new Set();
  while (queue.length) {
    const item = queue.shift();
    if (!item || item.value === null || typeof item.value !== 'object' || item.depth > maxDepth) continue;
    if (seen.has(item.value)) continue;
    seen.add(item.value);
    if (Array.isArray(item.value)) {
      for (const child of item.value) queue.push({ value: child, depth: item.depth + 1 });
      continue;
    }
    for (const key of Object.keys(item.value)) {
      if (wanted.has(key)) return item.value[key];
    }
    for (const key of Object.keys(item.value)) {
      const child = item.value[key];
      if (child !== null && typeof child === 'object') {
        queue.push({ value: child, depth: item.depth + 1 });
      } else if (typeof child === 'string') {
        const trimmedChild = child.trim();
        if (trimmedChild.startsWith('{') || trimmedChild.startsWith('[')) {
          const parsedChild = parseJsonIfString(trimmedChild, null);
          if (parsedChild !== null && typeof parsedChild === 'object') queue.push({ value: parsedChild, depth: item.depth + 1 });
        }
      }
    }
  }
  return undefined;
}

function normalizeRefArray(value) {
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    if (trimmed.startsWith('[')) {
      const parsed = parseJsonIfString(trimmed, null);
      if (Array.isArray(parsed)) return normalizeRefArray(parsed);
    }
    return trimmed.split(',').map((v) => v.trim()).filter(Boolean);
  }
  if (!Array.isArray(value)) return [];
  const refs = [];
  for (const item of value) {
    if (typeof item === 'string' && item.trim()) refs.push(item.trim());
    else if (isPlainObject(item)) {
      const ref = item.ref || item.id || item.name || item.static_context_ref || item.schema_ref;
      if (typeof ref === 'string' && ref.trim()) refs.push(ref.trim());
    }
  }
  return Array.from(new Set(refs));
}

function normalizeRoleRef(value) {
  if (Array.isArray(value) && value.length > 0) value = value[0];
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return null;
    return { role_id: trimmed, role_context_version: 'v1' };
  }
  if (!isPlainObject(value)) return null;
  const roleId = value.role_id || value.id || value.ref || value.name;
  const version = value.role_context_version || value.version || 'v1';
  if (typeof roleId !== 'string' || !roleId.trim()) return null;
  if (typeof version !== 'string' || !version.trim()) return null;
  return { role_id: roleId.trim(), role_context_version: version.trim() };
}

function detectFullStaticContextPaste(root) {
  const errors = [];
  const disallowedKeys = new Set([
    'static_context',
    'static_context_text',
    'static_contexts',
    'static_context_blob',
    'static_context_content',
    'full_static_context',
    'full_static_context_text',
    'context_paste',
    'pasted_static_context'
  ]);
  const markers = [
    'MOEX Bot — Target Architecture 2026',
    'Status: FROZEN TARGET SPEC',
    'Role Context Operating Model v1',
    'КРАТКАЯ ТЕХНИЧЕСКАЯ ИНСТРУКЦИЯ ДЛЯ SUB-ЧАТОВ',
    'GITHUB COMMIT FLOW',
    'GitHub = Source of Truth, Server = Applied State'
  ];
  const queue = [{ value: root, path: '$', depth: 0 }];
  const seen = new Set();
  while (queue.length) {
    const item = queue.shift();
    if (!item || item.value === null || item.depth > 8) continue;
    if (typeof item.value === 'string') {
      if (item.value.length > 1500 && markers.some((marker) => item.value.includes(marker))) {
        errors.push('full_static_context_text_pasted_at_' + item.path);
      }
      const trimmedValue = item.value.trim();
      if (trimmedValue.startsWith('{') || trimmedValue.startsWith('[')) {
        const parsedValue = parseJsonIfString(trimmedValue, null);
        if (parsedValue !== null && typeof parsedValue === 'object') queue.push({ value: parsedValue, path: item.path + '.$parsed', depth: item.depth + 1 });
      }
      continue;
    }
    if (typeof item.value !== 'object') continue;
    if (seen.has(item.value)) continue;
    seen.add(item.value);
    if (Array.isArray(item.value)) {
      for (let i = 0; i < item.value.length; i++) queue.push({ value: item.value[i], path: item.path + '[' + i + ']', depth: item.depth + 1 });
      continue;
    }
    for (const key of Object.keys(item.value)) {
      const lowerKey = key.toLowerCase();
      if (disallowedKeys.has(lowerKey)) errors.push('full_static_context_field_present_' + key);
      queue.push({ value: item.value[key], path: item.path + '.' + key, depth: item.depth + 1 });
    }
  }
  return Array.from(new Set(errors));
}

const claim = $input.first().json || {};
if (!claim.has_job) {
  return [];
}

let intakePayload = claim.intake_payload_json || {};
intakePayload = parseJsonIfString(intakePayload, {});
if (!isPlainObject(intakePayload)) intakePayload = {};

const requestRepositoryFullName = findFirstKey(intakePayload, ['repository_full_name'], 5);
const staticContextRefs = normalizeRefArray(findFirstKey(intakePayload, ['static_context_refs'], 5));
const roleContextRef = normalizeRoleRef(findFirstKey(intakePayload, ['role_context_ref'], 5));
const forbiddenTargetRoleContextRef = findFirstKey(intakePayload, ['target_role_context_ref'], 5);
const requestedSchemaRefs = normalizeRefArray(findFirstKey(intakePayload, ['schema_refs', 'required_schema_refs'], 5));
let dynamicHandoff = findFirstKey(intakePayload, ['dynamic_handoff'], 5);
dynamicHandoff = parseJsonIfString(dynamicHandoff, dynamicHandoff);

const attempt = Number(claim.attempt || (Number(claim.retry_count || 0) + 1));
const resolverErrors = [];

if (typeof requestRepositoryFullName !== 'string' || !requestRepositoryFullName.trim()) resolverErrors.push('missing_repository_full_name_in_request_payload');
if (typeof requestRepositoryFullName === 'string' && requestRepositoryFullName.trim() !== 'Viktoryyyyy/moex-robot') resolverErrors.push('repository_full_name_not_allowed');
if (claim.repository_full_name !== 'Viktoryyyyy/moex-robot') resolverErrors.push('claimed_repository_full_name_not_allowed');
if (staticContextRefs.length === 0) resolverErrors.push('missing_or_empty_static_context_refs');
if (forbiddenTargetRoleContextRef !== undefined) resolverErrors.push('target_role_context_ref_not_allowed_use_role_context_ref');
if (!roleContextRef) resolverErrors.push('missing_or_invalid_role_context_ref');
if (roleContextRef && roleContextRef.role_id !== 'PM_L3_DELIVERY_VALIDATION_OWNER') resolverErrors.push('role_context_ref_must_be_PM_L3_DELIVERY_VALIDATION_OWNER');
if (!isPlainObject(dynamicHandoff)) resolverErrors.push('missing_or_invalid_dynamic_handoff');
for (const ref of staticContextRefs) {
  if (!/^[A-Za-z0-9_.-]+$/.test(ref)) resolverErrors.push('invalid_static_context_ref_syntax_' + ref);
}
if (roleContextRef && !/^[A-Za-z0-9_.-]+$/.test(roleContextRef.role_id)) resolverErrors.push('invalid_role_context_ref_syntax');
if (roleContextRef && !/^[A-Za-z0-9_.-]+$/.test(roleContextRef.role_context_version)) resolverErrors.push('invalid_role_context_version_syntax');
for (const error of detectFullStaticContextPaste(intakePayload)) resolverErrors.push(error);

return [
  {
    json: {
      has_job: true,
      workflow_run_id: claim.workflow_run_id,
      idempotency_key: claim.idempotency_key,
      repository_full_name: claim.repository_full_name,
      request_repository_full_name: typeof requestRepositoryFullName === 'string' ? requestRepositoryFullName.trim() : null,
      target_branch_name: claim.target_branch_name,
      retry_count: claim.retry_count || 0,
      max_retries: claim.max_retries || 3,
      attempt,
      worker_execution_id: claim.worker_execution_id,
      claim_token: claim.claim_token,
      intake_payload_hash: hash32(stableStringify(intakePayload)),
      static_context_refs: staticContextRefs,
      role_context_ref: roleContextRef,
      dynamic_handoff: isPlainObject(dynamicHandoff) ? dynamicHandoff : null,
      dynamic_handoff_hash: isPlainObject(dynamicHandoff) ? hash32(stableStringify(dynamicHandoff)) : null,
      requested_schema_refs: requestedSchemaRefs,
      resolved_context_registry_path: 'docs/sot/context/registry.route_b.v1.yaml',
      resolved_context_registry_ref: 'main',
      context_resolver_errors: resolverErrors
    }
  }
];

function stableStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(stableStringify).join(',') + ']';
  return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stableStringify(value[key])).join(',') + '}';
}

function hash16(input) {
  let h1 = 0xdeadbeef ^ input.length;
  let h2 = 0x41c6ce57 ^ input.length;
  for (let i = 0; i < input.length; i++) {
    const ch = input.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return ((h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0')).slice(0, 16);
}

function hash32(input) {
  return hash16('a:' + input) + hash16('b:' + input);
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function decodeBase64(input) {
  const compact = String(input || '').replace(/\s+/g, '');
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(compact, 'base64').toString('utf8');
  }
  if (typeof atob !== 'undefined') {
    return decodeURIComponent(Array.prototype.map.call(atob(compact), function(c) {
      return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
    }).join(''));
  }
  throw new Error('base64_decoder_unavailable');
}

function decodeGitHubContent(response) {
  if (!response || response.error) throw new Error('registry_cannot_be_fetched');
  if (typeof response.content !== 'string') throw new Error('registry_response_missing_content');
  const encoding = String(response.encoding || '').toLowerCase();
  if (encoding && encoding !== 'base64') throw new Error('registry_response_unsupported_encoding');
  return decodeBase64(response.content);
}

function stripComment(line) {
  let inSingle = false;
  let inDouble = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    const prev = i > 0 ? line[i - 1] : '';
    if (ch === "'" && !inDouble) inSingle = !inSingle;
    else if (ch === '"' && !inSingle && prev !== '\\') inDouble = !inDouble;
    else if (ch === '#' && !inSingle && !inDouble) return line.slice(0, i);
  }
  return line;
}

function splitKeyValue(text) {
  let inSingle = false;
  let inDouble = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const prev = i > 0 ? text[i - 1] : '';
    if (ch === "'" && !inDouble) inSingle = !inSingle;
    else if (ch === '"' && !inSingle && prev !== '\\') inDouble = !inDouble;
    else if (ch === ':' && !inSingle && !inDouble) {
      const rawKey = text.slice(0, i).trim();
      const value = text.slice(i + 1).trim();
      if (!rawKey) return null;
      const key = rawKey.replace(/^['"]|['"]$/g, '');
      return { key, value };
    }
  }
  return null;
}

function parseScalar(value) {
  const trimmed = value.trim();
  if (trimmed === '') return {};
  if ((trimmed.startsWith('"') && trimmed.endsWith('"')) || (trimmed.startsWith("'") && trimmed.endsWith("'"))) return trimmed.slice(1, -1);
  if (trimmed === 'true') return true;
  if (trimmed === 'false') return false;
  if (trimmed === 'null' || trimmed === '~') return null;
  if (trimmed.startsWith('[') && trimmed.endsWith(']')) {
    const inner = trimmed.slice(1, -1).trim();
    if (!inner) return [];
    return inner.split(',').map((part) => parseScalar(part.trim()));
  }
  if (/^-?\d+(\.\d+)?$/.test(trimmed)) return Number(trimmed);
  return trimmed;
}

function prepareYamlLines(text) {
  const lines = [];
  const rawLines = text.replace(/\r\n/g, '\n').split('\n');
  for (const raw of rawLines) {
    if (raw.includes('\t')) throw new Error('registry_yaml_tab_indentation_not_supported');
    const noComment = stripComment(raw).replace(/\s+$/g, '');
    if (!noComment.trim()) continue;
    const indent = noComment.match(/^ */)[0].length;
    lines.push({ indent, text: noComment.trim() });
  }
  return lines;
}

function parseYamlBlock(lines, start, indent) {
  let i = start;
  if (i >= lines.length || lines[i].indent < indent) return [null, i];
  if (lines[i].indent !== indent) indent = lines[i].indent;
  if (lines[i].text.startsWith('- ')) {
    const arr = [];
    while (i < lines.length && lines[i].indent === indent && lines[i].text.startsWith('- ')) {
      const rest = lines[i].text.slice(2).trim();
      i += 1;
      let value;
      if (!rest) {
        if (i < lines.length && lines[i].indent > indent) {
          const parsed = parseYamlBlock(lines, i, lines[i].indent);
          value = parsed[0];
          i = parsed[1];
        } else value = null;
      } else {
        const kv = splitKeyValue(rest);
        if (kv) {
          const obj = {};
          if (kv.value === '') {
            if (i < lines.length && lines[i].indent > indent) {
              const parsed = parseYamlBlock(lines, i, lines[i].indent);
              obj[kv.key] = parsed[0];
              i = parsed[1];
            } else obj[kv.key] = {};
          } else obj[kv.key] = parseScalar(kv.value);
          if (i < lines.length && lines[i].indent > indent) {
            const parsed = parseYamlBlock(lines, i, lines[i].indent);
            if (isPlainObject(parsed[0])) Object.assign(obj, parsed[0]);
            else if (parsed[0] !== null) obj.items = parsed[0];
            i = parsed[1];
          }
          value = obj;
        } else {
          value = parseScalar(rest);
          if (i < lines.length && lines[i].indent > indent) {
            const parsed = parseYamlBlock(lines, i, lines[i].indent);
            value = { value, children: parsed[0] };
            i = parsed[1];
          }
        }
      }
      arr.push(value);
    }
    return [arr, i];
  }
  const obj = {};
  while (i < lines.length && lines[i].indent === indent && !lines[i].text.startsWith('- ')) {
    const kv = splitKeyValue(lines[i].text);
    if (!kv) throw new Error('registry_yaml_invalid_mapping_line');
    i += 1;
    if (kv.value === '') {
      if (i < lines.length && lines[i].indent > indent) {
        const parsed = parseYamlBlock(lines, i, lines[i].indent);
        obj[kv.key] = parsed[0];
        i = parsed[1];
      } else obj[kv.key] = {};
    } else obj[kv.key] = parseScalar(kv.value);
  }
  return [obj, i];
}

function parseSimpleYaml(text) {
  const lines = prepareYamlLines(text);
  if (lines.length === 0) throw new Error('registry_yaml_empty');
  const parsed = parseYamlBlock(lines, 0, lines[0].indent);
  if (parsed[1] < lines.length) throw new Error('registry_yaml_unparsed_tail');
  return parsed[0];
}

function parseRegistryText(text) {
  const trimmed = String(text || '').trim();
  if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
    return JSON.parse(trimmed);
  }
  return parseSimpleYaml(text);
}

function extractPath(value) {
  if (typeof value === 'string') return value;
  if (!isPlainObject(value)) return null;
  const candidates = ['path', 'repo_relative_path', 'file_path', 'file', 'document_path', 'schema_path'];
  for (const key of candidates) {
    if (typeof value[key] === 'string') return value[key];
  }
  return null;
}

function looksLikePath(value) {
  return typeof value === 'string' && (value.includes('/') || /\.(md|txt|yaml|yml|json)$/i.test(value));
}

function buildGenericRefMap(section) {
  const map = {};
  if (Array.isArray(section)) {
    for (const item of section) {
      if (!isPlainObject(item)) continue;
      const ref = item.ref || item.id || item.name || item.context_ref || item.static_context_ref || item.schema_ref;
      const path = extractPath(item);
      if (typeof ref === 'string' && path) map[ref] = { ref, path };
    }
  } else if (isPlainObject(section)) {
    for (const key of Object.keys(section)) {
      const value = section[key];
      const path = extractPath(value);
      if (path) map[key] = { ref: key, path };
      else if (looksLikePath(value)) map[key] = { ref: key, path: value };
    }
  }
  return map;
}

function buildRoleRefMap(section) {
  const map = {};
  if (Array.isArray(section)) {
    for (const item of section) {
      if (!isPlainObject(item)) continue;
      const roleId = item.role_id || item.ref || item.id || item.name;
      const version = item.role_context_version || item.version || 'v1';
      const path = extractPath(item);
      if (typeof roleId === 'string' && typeof version === 'string' && path) map[roleId + '@' + version] = { role_id: roleId, role_context_version: version, path };
    }
  } else if (isPlainObject(section)) {
    for (const roleId of Object.keys(section)) {
      const value = section[roleId];
      const directPath = extractPath(value);
      if (directPath) {
        const version = isPlainObject(value) && typeof value.version === 'string' ? value.version : 'v1';
        map[roleId + '@' + version] = { role_id: roleId, role_context_version: version, path: directPath };
      } else if (looksLikePath(value)) {
        map[roleId + '@v1'] = { role_id: roleId, role_context_version: 'v1', path: value };
      } else if (isPlainObject(value)) {
        for (const version of Object.keys(value)) {
          const nestedPath = extractPath(value[version]);
          if (nestedPath) map[roleId + '@' + version] = { role_id: roleId, role_context_version: version, path: nestedPath };
          else if (looksLikePath(value[version])) map[roleId + '@' + version] = { role_id: roleId, role_context_version: version, path: value[version] };
        }
      }
    }
  }
  return map;
}

function collectPathValues(value, out, path) {
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) collectPathValues(value[i], out, path + '[' + i + ']');
    return;
  }
  if (!isPlainObject(value)) return;
  for (const key of Object.keys(value)) {
    const child = value[key];
    const childPath = path + '.' + key;
    if (typeof child === 'string' && (key.toLowerCase().includes('path') || key.toLowerCase() === 'file' || looksLikePath(child))) out.push({ path: child, source: childPath });
    else collectPathValues(child, out, childPath);
  }
}

function validateRepoPath(path, label) {
  const errors = [];
  if (typeof path !== 'string' || !path.trim()) {
    errors.push(label + '_path_missing');
    return errors;
  }
  const p = path.trim();
  if (p.startsWith('/') || p.startsWith('~') || /^[A-Za-z]:[\\/]/.test(p)) errors.push(label + '_path_absolute_or_home');
  if (p.includes('..')) errors.push(label + '_path_contains_dotdot');
  if (p.includes('\\')) errors.push(label + '_path_contains_backslash');
  if (/^[a-z]+:\/\//i.test(p)) errors.push(label + '_path_contains_url_scheme');
  return errors;
}

function findForbiddenResolverMarkers(value, out, path) {
  if (typeof value === 'string') {
    const lower = value.toLowerCase();
    for (const marker of ['latest', 'current', 'autodetect']) {
      if (new RegExp('(^|[^a-z0-9_])' + marker + '([^a-z0-9_]|$)').test(lower)) out.push('registry_value_contains_forbidden_resolver_marker_' + marker + '_at_' + path);
    }
    return;
  }
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) findForbiddenResolverMarkers(value[i], out, path + '[' + i + ']');
    return;
  }
  if (isPlainObject(value)) {
    for (const key of Object.keys(value)) findForbiddenResolverMarkers(value[key], out, path + '.' + key);
  }
}

function encodeRepoPath(path) {
  return path.split('/').map((part) => encodeURIComponent(part)).join('/');
}

function firstNonEmptyObjectValue(object, keys) {
  for (const key of keys) {
    if (object && Object.prototype.hasOwnProperty.call(object, key)) return object[key];
  }
  return undefined;
}

const resolverInput = $('Prepare Context Resolver Input').item.json || {};
const registryResponse = $input.first().json || {};
const errors = [...(resolverInput.context_resolver_errors || [])];
let registryText = '';
let registry = null;
let staticMap = {};
let roleMap = {};
let schemaMap = {};

try {
  registryText = decodeGitHubContent(registryResponse);
} catch (error) {
  errors.push(error.message || 'registry_cannot_be_fetched');
}

if (registryText) {
  try {
    registry = parseRegistryText(registryText);
  } catch (error) {
    errors.push('registry_parse_failed:' + (error.message || 'unknown'));
  }
}

if (registry && !isPlainObject(registry)) errors.push('registry_root_must_be_mapping');

if (registry && isPlainObject(registry)) {
  const markerErrors = [];
  findForbiddenResolverMarkers(registry, markerErrors, '$');
  for (const error of markerErrors) errors.push(error);

  const pathValues = [];
  collectPathValues(registry, pathValues, '$');
  for (const item of pathValues) {
    for (const error of validateRepoPath(item.path, 'registry_' + item.source.replace(/[^A-Za-z0-9_]+/g, '_'))) errors.push(error);
  }

  staticMap = buildGenericRefMap(firstNonEmptyObjectValue(registry, ['static_context_refs', 'static_context', 'static_refs']));
  roleMap = buildRoleRefMap(firstNonEmptyObjectValue(registry, ['role_context_refs', 'role_contexts', 'role_refs']));
  schemaMap = buildGenericRefMap(firstNonEmptyObjectValue(registry, ['schema_refs', 'schemas', 'schema_context_refs']));
}

const requestedStaticRefs = resolverInput.static_context_refs || [];
