  if (!Array.isArray(parsed.proposed_file_changes)) fail('proposed_file_changes_must_be_array');
  if (parsed.forbidden_actions_acknowledged !== true) fail('forbidden_actions_acknowledged_must_be_true');
  if (Object.prototype.hasOwnProperty.call(parsed, 'target_branch_name') || Object.prototype.hasOwnProperty.call(parsed, 'github_branch_name')) fail('llm_must_not_choose_branch');

  if (Array.isArray(parsed.proposed_file_changes)) {
    for (let i = 0; i < parsed.proposed_file_changes.length; i++) {
      const change = parsed.proposed_file_changes[i];
      if (!isPlainObject(change)) {
        fail('proposed_file_change_must_be_object_' + i);
        continue;
      }
      const changeText = stableStringify(change).toLowerCase();
      if (changeText.includes('delete') || changeText.includes('remove') || changeText.includes('unlink') || changeText.includes('force_push') || changeText.includes('direct_main_write')) {
        fail('proposed_file_change_forbidden_operation_' + i);
      }
    }
  }

  for (const term of forbiddenTerms) {
    if (parsedText.includes(term)) fail('forbidden_term_detected_' + term);
  }
}

const isValid = validationErrors.length === 0;
const retryCount = Number(context.retry_count || 0);
const maxRetries = Number(context.max_retries || 3);
const attempt = Number(context.attempt || (retryCount + 1));
const nextRetryCount = retryCount + 1;
const canRetry = nextRetryCount < maxRetries;
const delayMinutes = Math.min(30, 5 * Math.pow(2, Math.max(0, nextRetryCount - 1)));
const nextRetryAt = new Date(Date.now() + delayMinutes * 60 * 1000).toISOString();

let runStatus;
let currentState;
let currentPhase;
let validationVerdict;
let eventType;
let stepStatus;
let errorMessage = null;
let nextRetryValue = null;
let fallbackRoute = null;
let durableEvidenceRef = null;
let incrementRetry = false;

if (isValid) {
  runStatus = 'ready_for_review';
  currentState = 'ready_for_review';
  currentPhase = 'pm_l3_package_drafted';
  validationVerdict = 'passed_deterministic_validation';
  eventType = 'worker_completed';
  stepStatus = 'completed';
  durableEvidenceRef = 'postgres:moex_n8n_workflow_run_events:' + context.workflow_run_id + ':worker_completed';
} else if (canRetry) {
  runStatus = 'retry_wait';
  currentState = 'retry_wait';
  currentPhase = 'worker_retry_wait';
  validationVerdict = 'failed_deterministic_validation';
  eventType = 'worker_failed_retry';
  stepStatus = 'failed_retryable';
  errorMessage = validationErrors.join(';');
  nextRetryValue = nextRetryAt;
  incrementRetry = true;
} else {
  runStatus = 'failed';
  currentState = 'failed';
  currentPhase = 'manual_review_required';
  validationVerdict = 'failed_deterministic_validation';
  eventType = 'worker_failed_final';
  stepStatus = 'failed_final';
  errorMessage = validationErrors.join(';');
  fallbackRoute = 'manual_pm_l3_review';
  incrementRetry = true;
}

const outputPayload = {
  workflow_name: 'MOEX_ROUTE_B_WORKER_POLLER_V1_10_3',
  spec_version: '1.10.3',
  workflow_run_id: context.workflow_run_id,
  repository_full_name: context.repository_full_name,
  attempt,
  validation_passed: isValid,
  validation_errors: validationErrors,
  llm_output: parsed,
  raw_content_hash: hash32(content || ''),
  action_type: parsed && parsed.action_type ? parsed.action_type : null,
  resolved_context_registry_path: context.resolved_context_registry_path || null,
  resolved_context_registry_ref: context.resolved_context_registry_ref || null,
  resolved_context_refs: context.resolved_context_refs || [],
  resolved_role_context_ref: context.resolved_role_context_ref || null,
  resolved_schema_refs: context.resolved_schema_refs || [],
  context_hash: context.context_hash || null,
  context_resolver_status: context.context_resolver_status || null,
  context_resolver_errors: context.context_resolver_errors || [],
  context_evidence: context.context_evidence || null,
  dynamic_handoff_hash: context.dynamic_handoff_hash || null
};

return [
  {
    json: {
      workflow_run_id: context.workflow_run_id,
      repository_full_name: context.repository_full_name,
      target_branch_name: context.target_branch_name,
      worker_execution_id: context.worker_execution_id,
      claim_token: context.claim_token,
      attempt,
      status: runStatus,
      current_state: currentState,
      current_phase: currentPhase,
      validation_verdict: validationVerdict,
      event_type: eventType,
      step_status: stepStatus,
      error_message: errorMessage,
      next_retry_at: nextRetryValue,
      fallback_route: fallbackRoute,
      durable_evidence_ref: durableEvidenceRef,
      increment_retry: incrementRetry,
      output_hash: hash32(stableStringify(outputPayload)),
      event_payload_json: JSON.stringify(outputPayload)
    }
  }
];
